func (q *Queries) ObserveAgentPullRequests(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, observeAgentPullRequests)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

