const setStanding = `-- name: SetStanding :one
WITH prior AS (
    SELECT
        held.id,
        held.last_known_checks,
        held.last_known_checks_sha,
        held.last_known_mergeability,
        held.last_known_decision
    FROM
        pull_requests held
    WHERE
        held.id = $7
    FOR UPDATE)
UPDATE
    pull_requests p
SET
    review_decision = $1,
    decision_changed_at = p.changed_at,
    checks = $2,
    mergeability = CASE WHEN $3::boolean THEN
        $4
    ELSE
        p.mergeability
    END,
    checks_sha = $5::text,
    checks_read_at = $6::timestamptz,
    last_known_checks = COALESCE($2, p.last_known_checks),
    last_known_checks_sha = CASE WHEN $2::text IS NULL THEN
        p.last_known_checks_sha
    ELSE
        NULLIF($5::text, '')
    END,
    last_known_mergeability = COALESCE($4, p.last_known_mergeability),
    last_known_mergeability_sha = CASE WHEN $4::text IS NULL THEN
        p.last_known_mergeability_sha
    ELSE
        NULLIF($5::text, '')
    END,
    last_known_decision = COALESCE($1, p.last_known_decision)
FROM
    prior
WHERE
    p.id = prior.id
RETURNING
    prior.last_known_checks AS old_checks,
    prior.last_known_checks_sha AS old_checks_sha,
    prior.last_known_mergeability AS old_mergeability,
    prior.last_known_decision AS old_decision,
    p.last_known_checks AS known_checks,
    p.last_known_checks_sha AS known_checks_sha,
    p.last_known_mergeability AS known_mergeability,
    p.last_known_decision AS known_decision
`

type SetStandingParams struct {
	ReviewDecision *string
	Checks         *string
	Answered       bool
	Mergeability   *string
	ChecksSha      string
	ChecksReadAt   time.Time
	ID             string
}

type SetStandingRow struct {
	OldChecks         *string
	OldChecksSha      *string
	OldMergeability   *string
	OldDecision       *string
	KnownChecks       *string
	KnownChecksSha    *string
	KnownMergeability *string
	KnownDecision     *string
}

func (q *Queries) SetStanding(ctx context.Context, arg SetStandingParams) (*SetStandingRow, error) {
	row := q.db.QueryRow(ctx, setStanding,
		arg.ReviewDecision,
		arg.Checks,
		arg.Answered,
		arg.Mergeability,
		arg.ChecksSha,
		arg.ChecksReadAt,
		arg.ID,
	)
	var i SetStandingRow
	err := row.Scan(
		&i.OldChecks,
		&i.OldChecksSha,
		&i.OldMergeability,
		&i.OldDecision,
		&i.KnownChecks,
		&i.KnownChecksSha,
		&i.KnownMergeability,
		&i.KnownDecision,
	)
	return &i, err
}

